    backtrack(nums, 0, res);
    return res;
}

private void backtrack(int[] nums, int index, List<List<Integer>> res) {
    if (index == nums.length) {
        List<Integer> list = new ArrayList<>();
        for (int num : nums) {
            list.add(num);
        }
        res.add(list);
        return;
    }
    for (int i = index; i < nums.length; i++) {
        int temp = nums[index];
        nums[index] = nums[i];
        nums[i] = temp;
        backtrack(nums, index + 1, res);
        // backtrack
        temp = nums[index];
        nums[index] = nums[i];
        nums[i] = temp;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Determine the shortest string length
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) {
        return 0;
    }
    String first = strings.get(0);
    // Try lengths from longest to shortest
    for (int len = minLen; len >= 1; len--) {
        // Collect unique substrings of current length from the first string
        Set<String> substrings = new HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            substrings.add(first.substring(i, i + len));
        }
        // Check each candidate substring
        for (String candidate : substrings) {
            String reverseCandidate = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(candidate) || s.contains(reverseCandidate))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

