public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int n = strings.size();
    // Find minimum length among all strings to bound binary search
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) return 0;
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) {
        return 0;
    }
    String first = strings.get(0);
    int low = 0, high = minLen;
    while (low < high) {
        int mid = (low + high + 1) / 2;
        if (existsCommonSubstringOfLength(first, strings, mid)) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

private boolean existsCommonSubstringOfLength(String first, List<String> strings, int len) {
    if (len == 0) return true;
    Set<String> substrSet = new HashSet<>();
    for (int i = 0; i <= first.length() - len; i++) {
        substrSet.add(first.substring(i, i + len));
    }
    for (String sub : substrSet) {
        String revSub = new StringBuilder(sub).reverse().toString();
        boolean ok = true;
        // check all strings (including the first one)
        for (String s : strings) {
            if (s == null) { ok = false; break; }
            if (!s.contains(sub) && !s.contains(revSub)) {
                ok = false;
                break;
            }
        }
        if (ok) {
            return true;
        }
    }
    return false;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int maxLen = first.length();
    // Check from longest to shortest
    for (int len = maxLen; len >= 1; len--) {
        Set<String> substrings = new HashSet<>();
        // Generate all substrings of length 'len' from first string
        for (int i = 0; i + len <= first.length(); i++) {
            String sub = first.substring(i, i + len);
            // add both the substring and its reverse to the candidate set
            // This ensures we test both directions but avoid double-checking
            substrings.add(sub);
            substrings.add(new StringBuilder(sub).reverse().toString());
        }
        // For each candidate, verify presence in all strings
        for (String cand : substrings) {
            boolean allMatch = true;
            for (int idx = 1; idx < strings.size(); idx++) {
                String s = strings.get(idx);
                if (!(s.contains(cand) || s.contains(new StringBuilder(cand).reverse().toString()))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int firstLen = first.length();
    int maxLen = 0;
    for (int i = 0; i < firstLen; i++) {
        for (int j = i + 1; j <= firstLen; j++) {
            int len = j - i;
            if (len <= maxLen) {
                continue;
            }
            String sub = first.substring(i, j);
            String revSub = new StringBuilder(sub).reverse().toString();
            boolean allMatch = true;
            for (int k = 1; k < strings.size(); k++) {
                String s = strings.get(k);
                if (!(s.contains(sub) || s.contains(revSub))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                maxLen = len;
            }
        }
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;
    int rows = grid.length;
    int cols = grid[0].length;
    if (cols == 0) return 0;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.add(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] cur = stack.removeLast();
                    int cr = cur[0], cc = cur[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dr[k];
                        int nc = cc + dc[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && !visited[nr][nc] && grid[nr][nc] == '@') {
                            visited[nr][nc] = true;
                            stack.add(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

