public static int maxRegions(int N) {
    if (N <= 0) {
        // Zero triangles: the whole plane is one region
        return 1;
    }
    // For the maximum number of regions contributed by triangles,
    // the first triangle creates 2 regions (inside and outside).
    // Every additional triangle can, in the optimal arrangement,
    // increase the number of regions by exactly 6.
    long regions = 2L + 6L * (N - 1L);
    if (regions > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Number of regions exceeds integer limits");
    }
    return (int) regions;
}

public static int maxRegions(int N) {
    if (N <= 0) {
        return 1; // No triangles produces one region (the whole plane)
    }
    long result = 3L * N * (N - 1) + 2;
    return (int) result;
}

public static int maxRegions(int N) {
    if (N <= 0) {
        return 1;
    }
    long result = 3L * N * N - 3L * N + 2L;
    return (int) Math.min(result, Integer.MAX_VALUE);
}

public static int maxRegions(int N) {
    if (N <= 0) {
        throw new IllegalArgumentException("Number of triangles must be positive");
    }
    long result = 3L * N * (N - 1) + 2L; // maximum regions: 3N^2 - 3N + 2
    if (result > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Result exceeds int range");
    }
    return (int) result;
}

