public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n < 0 || start == null || end == null || paths == null) {
            return "cannot be travelled";
        }
        // Ensure start and end contain at least one element
        if (start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }
        int startNode = start[0];
        int endNode = end[0];
        if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
            return "cannot be travelled";
        }

        // Build adjacency list
        List<List<Integer>> graph = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] path : paths) {
            if (path == null || path.length < 2) {
                continue; // ignore malformed path
            }
            int u = path[0];
            int v = path[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                continue; // ignore invalid indices
            }
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        // BFS
        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(startNode);
        visited[startNode] = true;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur == endNode) {
                return "can be travelled";
            }
            for (int neighbor : graph.get(cur)) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.offer(neighbor);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) {
        return "cannot be travelled";
    }
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int s = start[0];
    int t = end[0];
    if (s < 0 || s >= n || t < 0 || t >= n) {
        return "cannot be travelled";
    }
    if (s == t) {
        return "can be travelled";
    }
    @SuppressWarnings("unchecked")
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] p : paths) {
        if (p == null || p.length < 2) {
            continue;
        }
        int u = p[0];
        int v = p[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue;
        }
        adj[u].add(v);
        adj[v].add(u);
    }
    boolean[] visited = new boolean[n];
    Deque<Integer> queue = new ArrayDeque<>();
    visited[s] = true;
    queue.offer(s);
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int nb : adj[cur]) {
            if (!visited[nb]) {
                if (nb == t) {
                    return "can be travelled";
                }
                visited[nb] = true;
                queue.offer(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    if (paths == null) {
        paths = new int[0][];
    }
    String startKey = getKey(start);
    String endKey = getKey(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p == null || p.length != 2 * n) {
            continue;
        }
        int[] a = java.util.Arrays.copyOfRange(p, 0, n);
        int[] b = java.util.Arrays.copyOfRange(p, n, 2 * n);
        String aKey = getKey(a);
        String bKey = getKey(b);
        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbours = adj.get(cur);
        if (neighbours == null) {
            continue;
        }
        for (String nb : neighbours) {
            if (visited.contains(nb)) {
                continue;
            }
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(nb);
            queue.add(nb);
        }
    }
    return "cannot be travelled";
}

private static String getKey(int[] arr) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < arr.length; i++) {
        sb.append(arr[i]);
        if (i < arr.length - 1) {
            sb.append(',');
        }
    }
    return sb.toString();
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }

    int source = start[0];
    int destination = end[0];
    if (source < 0 || source >= n || destination < 0 || destination >= n) {
        return "cannot be travelled";
    }

    // Build adjacency list
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new java.util.ArrayList<>());
    }
    for (int[] path : paths) {
        if (path == null || path.length < 2) {
            continue; // invalid path entry
        }
        int u = path[0];
        int v = path[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue; // skip out‑of‑range references
        }
        adj.get(u).add(v);
        adj.get(v).add(u); // assume undirected path
    }

    // BFS to check reachability
    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    queue.add(source);
    visited[source] = true;

    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == destination) {
            return "can be travelled";
        }
        for (int next : adj.get(cur)) {
            if (!visited[next]) {
                visited[next] = true;
                queue.add(next);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    // Determine start and end node numbers
    int startNode = 0;
    if (start.length >= 1) {
        startNode = start[0];
    }
    int endNode = 0;
    if (end.length >= 1) {
        endNode = end[0];
    }
    // If start equals end, we can travel (already there)
    if (startNode == endNode) {
        return "can be travelled";
    }
    // Basic bounds check
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }
    // Build adjacency list
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] path : paths) {
        if (path == null || path.length < 2) continue;
        int u = path[0];
        int v = path[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        adj[u].add(v);
        adj[v].add(u);
    }
    // BFS
    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    queue.add(startNode);
    visited[startNode] = true;
    while (!queue.isEmpty()) {
        int current = queue.poll();
        for (int neighbor : adj[current]) {
            if (!visited[neighbor]) {
                if (neighbor == endNode) {
                    return "can be travelled";
                }
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Input date string cannot be null or empty");
    }
    try {
        java.time.format.DateTimeFormatter inputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy", java.util.Locale.ENGLISH);
        java.time.LocalDate parsedDate = java.time.LocalDate.parse(date.trim(), inputFormatter);

        java.time.format.DateTimeFormatter outputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy", java.util.Locale.ENGLISH);
        String formattedDate = parsedDate.format(outputFormatter);

        java.time.DayOfWeek dayOfWeek = parsedDate.getDayOfWeek();
        String weekday = dayOfWeek.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return formattedDate + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid date format, expected 'MM dd yyyy'", e);
    }
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid date";
        }
        int month = Integer.parseInt(parts[0]);
        int day   = Integer.parseInt(parts[1]);
        int year  = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            return "Invalid date";
        }

        java.util.Calendar cal = java.util.Calendar.getInstance();
        cal.setLenient(false);
        cal.set(java.util.Calendar.YEAR, year);
        cal.set(java.util.Calendar.MONTH, month - 1); // Calendar months are 0-based
        cal.set(java.util.Calendar.DAY_OF_MONTH, day);
        // Force validation
        cal.getTime();

        String[] monthNames = {"January", "February", "March", "April", "May", "June",
                               "July", "August", "September", "October", "November", "December"};
        String[] weekDays   = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday",
                               "Friday", "Saturday"};

        String monthName = monthNames[month - 1];
        String weekday   = weekDays[cal.get(java.util.Calendar.DAY_OF_WEEK) - 1];

        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (Exception e) {
        return "Invalid date";
    }
}

