public double trimMean(int[] arr) {
    int n = arr.length;
    if (n == 0) return 0.0;
    int discard = (int)Math.floor(n * 0.05);
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = discard; i < n - discard; i++) {
        sum += sorted[i];
    }
    int count = n - 2 * discard;
    return count > 0 ? (double) sum / count : 0.0;
}

