private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
    int total = 0;
    for (int child : graph[node]) {
        if (child == parent) continue;
        int childTime = dfs(child, node, graph, hasApple);
        // If child subtree has an apple or the child itself has an apple,
        // we need to visit this edge twice (go and back)
        if (childTime > 0 || hasApple[child]) {
            total += childTime + 2;
        }
    }
    return total;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) {
        return 0;
    }
    // Build adjacency list using primitive arrays
    int[] degree = new int[n];
    for (int[] e : edges) {
        degree[e[0]]++;
        degree[e[1]]++;
    }
    int[][] neighbors = new int[n][];
    for (int i = 0; i < n; i++) {
        neighbors[i] = new int[degree[i]];
    }
    int[] cursor = new int[n];
    for (int[] e : edges) {
        int u = e[0];
        int v = e[1];
        neighbors[u][cursor[u]++] = v;
        neighbors[v][cursor[v]++] = u;
    }

    // Tree traversal to record parent and order
    int[] parent = new int[n];
    int[] order = new int[n];
    int[] stack = new int[n];
    int top = 0;
    int ordIdx = 0;
    stack[top++] = 0;
    parent[0] = -1;
    while (top > 0) {
        int node = stack[--top];
        order[ordIdx++] = node;
        for (int nb : neighbors[node]) {
            if (nb == parent[node]) {
                continue;
            }
            parent[nb] = node;
            stack[top++] = nb;
        }
    }

    // Post-order processing to accumulate travel time
    int total = 0;
    boolean[] has = new boolean[n];
    for (int i = ordIdx - 1; i >= 0; i--) {
        int node = order[i];
        boolean need = hasApple[node];
        for (int nb : neighbors[node]) {
            if (parent[nb] == node) { // child
                if (has[nb]) {
                    need = true;
                    total += 2;
                }
            }
        }
        has[node] = need;
    }
    return total;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    // Count frequencies of ASCII characters (0-127)
    int[] freq = new int[128];
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c < freq.length) {
            freq[c]++;
        } else {
            // For non-ASCII characters, extend the array size
            // This scenario is unlikely per problem constraints
            // but we handle it gracefully by ignoring the char
        }
    }

    StringBuilder result = new StringBuilder(s.length());
    while (result.length() < s.length()) {
        // Ascending phase: from smallest to largest
        for (int i = 0; i < freq.length; i++) {
            if (freq[i] > 0) {
                result.append((char) i);
                freq[i]--;
            }
        }
        if (result.length() == s.length()) {
            break;
        }
        // Descending phase: from largest to smallest
        for (int i = freq.length - 1; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) i);
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return "";
    }
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c >= 'a' && c <= 'z') {
            freq[c - 'a']++;
        } else {
            // If characters outside 'a'-'z' appear, treat them independently by using a separate strategy:
            // For simplicity, we return the original string for such cases.
            return s;
        }
    }
    StringBuilder sb = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending part
        int i = 0;
        while (i < 26 && freq[i] == 0) {
            i++;
        }
        if (i == 26) break;
        sb.append((char) ('a' + i));
        freq[i]--;
        remaining--;
        int last = i;
        for (int j = last + 1; j < 26; j++) {
            if (freq[j] > 0) {
                sb.append((char) ('a' + j));
                freq[j]--;
                remaining--;
                last = j;
            }
        }
        if (remaining == 0) break;
        // Descending part
        for (int j = 25; j >= 0; j--) {
            if (freq[j] > 0) {
                sb.append((char) ('a' + j));
                freq[j]--;
                remaining--;
                last = j;
                for (int k = last - 1; k >= 0; k--) {
                    if (freq[k] > 0) {
                        sb.append((char) ('a' + k));
                        freq[k]--;
                        remaining--;
                        last = k;
                    }
                }
                break;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    // sets[k] will contain all achievable sums with exactly k elements
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] sets = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sets[i] = new java.util.HashSet<>();
    }
    sets[0].add(0);

    // Build subset sum sets
    for (int num : nums) {
        // iterate k backwards to avoid using the same number twice
        for (int k = n - 1; k >= 0; k--) {
            if (sets[k].isEmpty()) continue;
            java.util.HashSet<Integer> current = sets[k];
            java.util.HashSet<Integer> next = sets[k + 1];
            for (int s : current) {
                next.add(s + num);
            }
        }
    }

    // Check for any valid split
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) continue;
        int targetSum = (totalSum * k) / n;
        if (sets[k].contains(targetSum)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    // Iterate over possible subset sizes
    for (int k = 1; k <= n / 2; k++) {
        long product = 1L * total * k;
        if (product % n != 0) {
            continue; // target sum not integer
        }
        int target = (int) (product / n);
        // Dynamic programming: store achievable sums for each subset size
        // We only need one set for current k
        java.util.HashSet<Integer> sums = new java.util.HashSet<>();
        sums.add(0);
        for (int num : nums) {
            // create new sums by adding current number to existing ones
            java.util.ArrayList<Integer> newSums = new java.util.ArrayList<>();
            for (int s : sums) {
                int ns = s + num;
                newSums.add(ns);
            }
            sums.addAll(newSums);
            if (sums.contains(target)) {
                return true;
            }
        }
    }
    return false;
}

