public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return 0; // only one step, can start on it and go straight to the top with no cost
    }
    // dp[0] = cost[0], dp[1] = cost[1]
    int prevPrev = cost[0];
    int prev = cost[1];
    for (int i = 2; i < n; i++) {
        int cur = Math.min(prev, prevPrev) + cost[i];
        prevPrev = prev;
        prev = cur;
    }
    return Math.min(prev, prevPrev); // minimum cost to step beyond the last stair
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0; // can start from index 1 (top) with no cost
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 1 (top) with zero cost.
        return 0;
    }
    int dpPrev2 = cost[0]; // dp[i-2]
    int dpPrev1 = cost[1]; // dp[i-1]
    for (int i = 2; i < n; i++) {
        int cur = cost[i] + Math.min(dpPrev2, dpPrev1);
        dpPrev2 = dpPrev1;
        dpPrev1 = cur;
    }
    return Math.min(dpPrev2, dpPrev1);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Only one step, you can start at it or skip; min cost is 0 if you start at top directly
        return 0;
    }
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0 || n == 1) {
        // If there are less than two steps, the top can be reached without paying any cost
        return 0;
    }
    // dp[i] represents the minimum cost to reach step i
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    // The top is after step n-1, so it can be reached from either step n-1 or n-2
    return Math.min(dp[n - 1], dp[n - 2]);
}

