public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k < 0) {
        return false;
    }
    // Edge case: empty pattern (k == 0) is trivially present
    if (k == 0) {
        return true;
    }
    int n = s.length();
    // If the string is too short to contain all possible codes
    if (n < k) {
        return false;
    }
    int totalCodes = 1 << k;          // 2^k possible binary strings
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;        // Mask to keep only k bits
    int current = 0;
    int countSeen = 0;

    for (int i = 0; i < n; i++) {
        // Build the integer value of the current window
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {            // window is full size
            if (!seen[current]) {
                seen[current] = true;
                countSeen++;
                // Early exit if all codes are seen
                if (countSeen == totalCodes) {
                    return true;
                }
            }
        }
    }
    return countSeen == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) {
        // The only binary string of length 0 is the empty string, which is always a substring.
        return true;
    }
    if (s == null || s.length() < k) {
        return false;
    }
    // Risk of integer overflow if k >= 31. In that case 2^k exceeds int range,
    // and the string cannot contain all such codes by length constraints.
    if (k >= 31) {
        return false;
    }
    int totalCodes = 1 << k;
    // Quick check: there must be at least totalCodes substrings of length k.
    if (s.length() - k + 1 < totalCodes) {
        return false;
    }

    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;
    int value = 0;

    // Build initial value for the first window.
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    seen[value] = true;
    int seenCount = 1;

    // Slide over the rest of the string.
    for (int i = k; i < s.length(); i++) {
        value = ((value << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[value]) {
            seen[value] = true;
            seenCount++;
            if (seenCount == totalCodes) {
                return true; // All codes seen early.
            }
        }
    }

    return seenCount == totalCodes;
}

