    }
    long maxEnding = 0;
    long maxOverall = Long.MIN_VALUE;
    long minEnding = 0;
    long minOverall = Long.MAX_VALUE;
    for (int num : nums) {
        // Update maximum ending here
        maxEnding = Math.max(num, maxEnding + num);
        maxOverall = Math.max(maxOverall, maxEnding);
        // Update minimum ending here
        minEnding = Math.min(num, minEnding + num);
        minOverall = Math.min(minOverall, minEnding);
    }
    long result = Math.max(Math.abs(maxOverall), Math.abs(minOverall));
    // Clamp to int range
    if (result > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }
    if (result < Integer.MIN_VALUE) {
        return Integer.MIN_VALUE;
    }
    return (int) result;
}

