    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int rem = k - small.size();
        // large list is in descending order, so pick from the end
        return large.get(large.size() - rem);
    }
}

