public int maxUniqueSplit(String s) {
    return dfs(0, s, new java.util.HashSet<>());
}

private int dfs(int idx, String s, java.util.Set<String> used) {
    if (idx == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int count = 1 + dfs(end, s, used);
            if (count > max) {
                max = count;
            }
            used.remove(sub);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] best = new int[1];
    best[0] = 0;
    dfs(0, new java.util.HashSet<>(), 0, s, best, n);
    return best[0];
}

private void dfs(int pos, java.util.Set<String> used, int count, String s, int[] best, int n) {
    if (pos == n) {
        if (count > best[0]) best[0] = count;
        return;
    }
    // pruning: maximum possible remaining splits equal to n - pos
    if (count + (n - pos) <= best[0]) return;
    for (int end = pos + 1; end <= n; end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, used, count + 1, s, best, n);
            used.remove(sub);
        }
    }
}

