private void dfs(int pos, Set<String> used, String s, int[] best) {
    if (pos == s.length()) {
        if (used.size() > best[0]) {
            best[0] = used.size();
        }
        return;
    }
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, used, s, best);
            used.remove(sub);
        }
    }
}

