private int dfs(String s, int idx, java.util.Set<String> used) {
    if (idx == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int curr = 1 + dfs(s, end, used);
            if (curr > max) {
                max = curr;
            }
            used.remove(sub);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) return 0;
    int n = s.length();
    int[] best = new int[]{0};
    java.util.HashSet<String> used = new java.util.HashSet<>();
    class DFS {
        void search(int pos) {
            if (pos == n) {
                if (used.size() > best[0]) best[0] = used.size();
                return;
            }
            for (int end = pos + 1; end <= n; end++) {
                String part = s.substring(pos, end);
                if (used.add(part)) {
                    search(end);
                    used.remove(part);
                }
            }
        }
    }
    new DFS().search(0);
    return best[0];
}

public int minOperations(String[] logs) {
    int depth = 0;
    if (logs == null) {
        return 0;
    }
    for (String log : logs) {
        if ("../".equals(log)) {
            if (depth > 0) {
                depth--;
            }
        } else if ("./".equals(log)) {
            // stay in the current folder
            continue;
        } else if (log != null && log.endsWith("/")) {
            // enter a new folder
            depth++;
        }
    }
    return depth;
}

