public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    if (k < n || k > 26L * n) {
        throw new IllegalArgumentException("k is out of the valid range");
    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    long diff = k - n;
    for (int i = n - 1; i >= 0 && diff > 0; i--) {
        int add = (int) Math.min(25, diff);
        result[i] = (char) ('a' + add);
        diff -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) return "";
    int minSum = n;          // all 'a'
    int maxSum = 26 * n;     // all 'z'
    if (k < minSum || k > maxSum) return "";

    char[] result = new char[n];
    int remaining = k;

    for (int i = n - 1; i >= 0; i--) {
        int minRemainingSum = i; // minimum sum for the remaining i positions (each at least 1)
        int value = Math.min(26, remaining - minRemainingSum);
        result[i] = (char) ('a' + value - 1);
        remaining -= value;
    }

    return new String(result);
}

