        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int minSum = n;          // all 'a's
    int maxSum = n * 26;     // all 'z's
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k must be between " + minSum + " and " + maxSum);
    }

    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a'); // initial string of 'a's
    int diff = k - minSum;              // additional value needed

    for (int i = n - 1; i >= 0 && diff > 0; i--) {
        int increase = Math.min(25, diff); // max increase for one character
        result[i] += increase;
        diff -= increase;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) return "";
    int minValue = n;          // all 'a' -> value 1 each
    int maxValue = n * 26;     // all 'z'
    if (k < minValue || k > maxValue) {
        throw new IllegalArgumentException("k must be between " + minValue + " and " + maxValue);
    }
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int remaining = k - minValue;  // how much value we need to add
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can add up to 25 more (a->z)
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

