public static int singleNumber(int[] nums) {
    int[] counts = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            counts[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((counts[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        // Update bits that have appeared once and not in twice.
        ones = (ones ^ num) & ~twos;
        // Update bits that have appeared twice and not in once.
        twos = (twos ^ num) & ~ones;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int bit = 0; bit < 32; bit++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> bit) & 1;
        }
        if ((sum % 3) != 0) {
            result |= (1 << bit);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        int mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

