}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    if (low <= 0) {
        result.add(0);
    }
    Queue<Long> queue = new ArrayDeque<>();
    for (int d = 1; d <= 9; d++) {
        queue.offer((long) d);
    }
    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur > high) {
            continue;
        }
        if (cur >= low) {
            result.add((int) cur);
        }
        int last = (int) (cur % 10);
        if (last > 0) {
            long next = cur * 10 + (last - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (last < 9) {
            long next = cur * 10 + (last + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) {
        return result;
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    // Handle single digit 0 separately
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    // Enqueue numbers 1-9 as starting points
    for (int num = 1; num <= 9; num++) {
        queue.offer((long) num);
    }
    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            if (current <= Integer.MAX_VALUE) {
                result.add((int) current);
            }
        }
        long lastDigit = current % 10;
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    // Invalid range handling
    if (high < 0 || low > high) {
        return result;
    }
    // Stepping numbers are non‑negative
    low = Math.max(0, low);
    if (low == 0 && high >= 0) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    // Start BFS from numbers 1 to 9
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur > high) {
            continue;
        }
        if (cur >= low) {
            result.add((int) cur);
        }
        long lastDigit = cur % 10;
        // Next digit can be lastDigit-1
        if (lastDigit > 0) {
            long next = cur * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        // Next digit can be lastDigit+1
        if (lastDigit < 9) {
            long next = cur * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) return result;
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int d = 0; d <= 9; d++) {
        long num = d;
        if (num == 0) {
