public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    int count = 0;
    long pos = 1;
    while (n / pos > 0) {
        int high = (int) (n / (pos * 10));
        int cur = (int) ((n / pos) % 10);
        int low = (int) (n % pos);

        if (cur == 0) {
            count += high * (int) pos;
        } else if (cur == 1) {
            count += high * (int) pos + low + 1;
        } else {
            count += (high + 1) * (int) pos;
        }
        pos *= 10;
    }
    return count;
}

public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    long count = 0;
    long factor = 1;
    long nn = n;
    while (factor <= nn) {
        long lower = nn - (nn / factor) * factor;
        long cur = (nn / factor) % 10;
        long higher = nn / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        if (factor > Long.MAX_VALUE / 10) break;
        factor *= 10;
    }
    return (int) count;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long num = n;
    for (long factor = 1; factor <= num; factor *= 10) {
        long lower = num - (num / factor) * factor;
        long cur = (num / factor) % 10;
        long higher = num / (factor * 10);
        if (cur == 0) {
