public static int addDigits(int num) {
    // Ensure the input is non-negative; if negative, take absolute value
    if (num < 0) {
        num = -num;
    }
    // Repeatedly sum the digits until a single digit remains
    while (num >= 10) {
        int sum = 0;
        int temp = num;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
        num = sum;
    }
    return num;
}

