public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute adjacency lists
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                adj[i].add(j);
            }
        }
    }
    int fullMask = (1 << n) - 1;
    int[][] dp = new int[1 << n][n];
    // Initialize DP
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    // Build DP
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            int curCount = dp[mask][last];
            if (curCount == 0) continue;
            for (int next : adj[last]) {
                if ((mask & (1 << next)) == 0) {
                    dp[mask | (1 << next)][next] += curCount;
                }
            }
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int max = 0;
    for (int v : A) if (v > max) max = v;
    int limit = 2 * max;
    boolean[] square = new boolean[limit + 1];
    for (int i = 0; i * i <= limit; i++) square[i * i] = true;
    java.util.Arrays.sort(A);
    boolean[] visited = new boolean[n];
    return (int) dfs(-1, 0, A, visited, square);
}

private static long dfs(int prevIdx, int depth, int[] A, boolean[] visited, boolean[] square) {
    int n = A.length;
    if (depth == n) return 1L;
    long total = 0;
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
        if (prevIdx == -1 || square[A[prevIdx] + A[i]]) {
            visited[i] = true;
            total += dfs(i, depth + 1, A, visited, square);
            visited[i] = false;
        }
    }
    return total;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 1;
    }
    // Build frequencies of each unique value
    java.util.HashMap<Integer, Integer> freqMap = new java.util.HashMap<>();
    int maxVal = 0;
    for (int v : A) {
        freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
        if (v > maxVal) maxVal = v;
    }
    int maxSum = maxVal * 2;
    java.util.HashSet<Integer> squares = new java.util.HashSet<>();
    for (int i = 1; i * i <= maxSum; i++) {
        squares.add(i * i);
    }

    java.util.List<Integer> values = new java.util.ArrayList<>(freqMap.keySet());
    int m = values.size();
    int[] remain = new int[m];
    for (int i = 0; i < m; i++) {
        remain[i] = freqMap.get(values.get(i));
    }

    java.util.Map<String, Integer> memo = new java.util.HashMap<>();
    return dfs(null, remain, A.length, m, values, squares, memo);
}

private static int dfs(
        Integer last,
        int[] remain,
        int remaining,
        int m,
        java.util.List<Integer> values,
        java.util.Set<Integer> squares,
        java.util.Map<String, Integer> memo) {
    if (remaining == 0) {
        return 1;
    }
    StringBuilder keyBuilder = new StringBuilder();
    keyBuilder.append(last == null ? "null" : last);
    keyBuilder.append("|");
    for (int i = 0; i < m; i++) {
        keyBuilder.append(remain[i]).append(",");
    }
    String key = keyBuilder.toString();
    if (memo.containsKey(key)) {
        return memo.get(key);
    }

    int total = 0;
    for (int i = 0; i < m; i++) {
        if (remain[i] == 0) continue;
        int val = values.get(i);
        if (last == null || squares.contains(last + val)) {
            remain[i]--;
            total += dfs(val, remain, remaining - 1, m, values, squares, memo);
            remain[i]++;
        }
    }
    memo.put(key, total);
    return total;
}

