}

private static void dfs(int depth, int lastVal, boolean[] used, int[] A, int[] count, int n) {
    if (depth == n) {
        count[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (depth > 0 && !isSquare(A[i] + lastVal)) continue;
        // Skip duplicates
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;

        used[i] = true;
        dfs(depth + 1, A[i], used, A, count, n);
        used[i] = false;
    }
}

private static boolean isSquare(int x) {
    int s = (int)Math.sqrt(x);
    return s * s == x;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int n = A.length;
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) {
            maxVal = v;
        }
    }
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int s = 0; s * s <= maxSum; ++s) {
        isSquare[s * s] = true;
    }
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    java.util.ArrayList<Integer> perm = new java.util.ArrayList<>(n);
    java.util.ArrayList<Integer> result = new java.util.ArrayList<>();
    java.util.function.LongConsumer counter = (val) -> { result.add((int) val); };
    final long[] count = {0};

    java.util.function.IntConsumer dfs = new java.util.function.IntConsumer() {
        @Override
        public void accept(int depth) {
            if (depth == n) {
                count[0]++;
                return;
            }
            for (int i = 0; i < n; ++i) {
                if (used[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
                if (depth > 0) {
                    int sum = A[i] + perm.get(depth - 1);
                    if (!isSquare[sum]) continue;
                }
                used[i] = true;
                perm.add(A[i]);
                accept(depth + 1);
                perm.remove(perm.size() - 1);
                used[i] = false;
            }
        }
    };

    dfs.accept(0);
    return (int) count[0];
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(-1); // Sentinel value to simplify width calculation
    for (int i = 0; i <= heights.length; i++) {
        int currentHeight = (i == heights.length) ? 0 : heights[i];
        while (stack.peek() != -1 && heights[stack.peek()] > currentHeight) {
            int height = heights[stack.pop()];
            int width = i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

