        int rowEnd = Math.min(m - 1, d);
        if (d % 2 == 0) {
            for (int r = rowEnd; r >= rowStart; r--) {
                int c = d - r;
                result[index++] = mat[r][c];
            }
        } else {
            for (int r = rowStart; r <= rowEnd; r++) {
                int c = d - r;
                result[index++] = mat[r][c];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    // Convert the number into an array of its digits
    String s = Integer.toString(n);
    int len = s.length();
    int[] digits = new int[len];
    for (int i = 0; i < len; i++) {
        digits[i] = s.charAt(i) - '0';
    }

    // Find the first index 'i' from the right where digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such index exists, the digits are in descending order – no larger permutation
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right of i that is greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    int temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the sub-array from i+1 to the end
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert the digit array back to an integer
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
    }

    // Result must fit within the int range
    if (result > Integer.MAX_VALUE) {
        return -1;
    }

    return (int) result;
}

