public static java.util.List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        java.util.List<String> empty = new java.util.ArrayList<>();
        return empty;
    }
    return find(n, n);
}

private static java.util.List<String> find(int n, int total) {
    if (n == 0) {
        java.util.List<String> base = new java.util.ArrayList<>();
        base.add("");
        return base;
    }
    if (n == 1) {
        java.util.List<String> base = new java.util.ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    java.util.List<String> inner = find(n - 2, total);
    java.util.List<String> result = new java.util.ArrayList<>();
    for (java.lang.String s : inner) {
        if (n != total) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) return result;
    char[] leftOptions = {'0','1','8','6','9'};
    char[] rightOptions = {'0','1','8','9','6'};
    char[] middleOptions = {'0','1','8'};
    char[] cur = new char[n];
    class Generator {
        void gen(int l, int r) {
            if (l > r) {
                result.add(new String(cur));
            } else if (l == r) {
                for (char d : middleOptions) {
                    cur[l] = d;
                    gen(l + 1, r - 1);
                }
            } else {
                for (int i = 0; i < 5; i++) {
                    char left = leftOptions[i];
                    if (l == 0 && n > 1 && left == '0') continue;
                    char right = rightOptions[i];
                    cur[l] = left;
                    cur[r] = right;
                    gen(l + 1, r - 1);
                }
            }
        }
    }
    new Generator().gen(0, n - 1);
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = {
        {'0', '0'},
        {'1', '1'},
        {'8', '8'},
        {'6', '9'},
        {'9', '6'}
    };
    char[] current = new char[n];

    java.util.function.BiConsumer<Integer, Integer> backtrack = new java.util.function.BiConsumer<Integer, Integer>() {
        @Override
        public void accept(Integer left, Integer right) {
            if (left > right) {
                result.add(new String(current));
                return;
            }
            if (left == right) {
                for (char middle : new char[]{'0', '1', '8'}) {
                    current[left] = middle;
                    result.add(new String(current));
                }
                return;
            }
            for (char[] pair : pairs) {
                if (left == 0 && pair[0] == '0' && n > 1) {
                    continue; // avoid leading zero for multi-digit numbers
                }
                current[left] = pair[0];
                current[right] = pair[1];
                accept(left + 1, right - 1);
            }
        }
    };

    backtrack.accept(0, n - 1);
    return result;
}

public class CenterSymmetricNumbers {
    public static java.util.List<java.lang.String> centerSymmetricNumbers(int n) {
        if (n <= 0) {
            return new java.util.ArrayList<java.lang.String>();
        }
        return build(n, n);
    }

    private static java.util.List<java.lang.String> build(int current, int total) {
        if (current == 0) {
            java.util.List<java.lang.String> base = new java.util.ArrayList<java.lang.String>();
            base.add("");
            return base;
        }
        if (current == 1) {
            java.util.List<java.lang.String> mid = new java.util.ArrayList<java.lang.String>();
            mid.add("0");
            mid.add("1");
            mid.add("8");
            return mid;
        }

        java.util.List<java.lang.String> result = new java.util.ArrayList<java.lang.String>();
        java.util.List<java.lang.String> inner = build(current - 2, total);
        char[][] pairs = { {'0', '0'}, {'1', '1'}, {'8', '8'}, {'6', '9'}, {'9', '6'} };

        for (char[] pair : pairs) {
            if (current == total && pair[0] == '0') {
                continue; // avoid leading zero
            }
            for (java.lang.String midStr : inner) {
                result.add(pair[0] + midStr + pair[1]);
            }
        }
        return result;
    }
}

