public class CenterSymmetricNumberGenerator {
    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        char[] buffer = new char[n];
        backtrack(buffer, 0, n - 1, result);
        return result;
    }

    private static void backtrack(char[] buffer, int left, int right, List<String> result) {
        if (left > right) {
            result.add(new String(buffer));
            return;
        }
        if (left == right) {
            for (char c : new char[]{'0', '1', '8'}) {
                buffer[left] = c;
                backtrack(buffer, left + 1, right - 1, result);
            }
            return;
        }

        char[][] pairs = {
            {'1', '1'},
            {'6', '9'},
            {'8', '8'},
            {'9', '6'}
        };
        for (char[] pair : pairs) {
            if (left == 0 && pair[0] == '0' && buffer.length > 1) {
                continue; // skip leading zero
            }
            buffer[left] = pair[0];
            buffer[right] = pair[1];
            backtrack(buffer, left + 1, right - 1, result);
        }
    }
}

public static boolean isBoomerang(int[][] points) {
    // Validate the input
    if (points == null || points.length != 3) {
        return false;
    }

    // Check for duplicate points
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }

    // Compute the area of the triangle formed by the points
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    int area = (x1 * y2 + x2 * y3 + x3 * y1) - (x2 * y1 + x3 * y2 + x1 * y3);

    return area != 0;
}

