public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>(n);
    if (n <= 0) {
        return res;
    }
    int curr = 1;
    for (int i = 0; i < n; i++) {
        res.add(curr);
        long next = (long) curr * 10L;
        if (next <= n) {
            curr = (int) next;
        } else if (curr % 10 != 9 && curr + 1 <= n) {
            curr++;
        } else {
            while (curr / 10 % 10 == 9) {
                curr /= 10;
            }
            curr = curr / 10 + 1;
        }
    }
    return res;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int num, int n, List<Integer> res) {
    if (num > n) return;
    res.add(num);
    for (int d = 0; d <= 9; d++) {
        long next = (long) num * 10 + d;
        if (next > n) break;
        dfs((int) next, n, res);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> frequency = new java.util.HashMap<>();
    for (int num : nums) {
        frequency.put(num, frequency.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

